// Direct imports avoid barrel re-export in store/main (saves ~280 KB from initial load)
import { useWebSocketStore } from 'src/store/websocket.store';
import { useAuthTokenStore } from 'src/store/User/auth_token.store';
import { initializeNetworkStatus, cleanupNetworkStatus } from 'src/composables/useNetworkStatus';
import { initializeConnectionNotifications } from 'src/services/notifications/ConnectionNotificationService';
import { useDocNetWebSocketStore } from 'src/store/DocNet/docnet-websocket.store';
import { useSettingStore } from 'src/store/Settings/setting.store';
import subscriptionUtil from 'src/utils/subscriptionUtil';
import { CONSTANTS } from 'src/constants';
import { safeBoot } from 'src/utils/bootSafety';
import { toBoolPreference } from 'src/utils/preferenceBool';

// HMR guard to prevent multiple initializations during hot reload
let isInitialized = false;
let beforeUnloadHandler = null;

export default safeBoot('websocket', async ({ app, router }) => {
  // Prevent re-initialization during HMR
  if (isInitialized && import.meta.hot) {
    console.debug('[WebSocket Boot] Skipping re-initialization (HMR)');
    return;
  }
  try {
    // Check if current route is /auth and skip execution if it is
    if (
      typeof window !== 'undefined' &&
      window.location.pathname.startsWith('/auth')
    ) {
      return;
    }

    const auth_token_store = useAuthTokenStore();
    const isLoggedIn = await auth_token_store.isLoggedIn();
    if (!isLoggedIn) {
      return;
    }

    // Initialize the WebSocket store
    const webSocketStore = useWebSocketStore();

    // Initialize network status detection (global listeners)
    initializeNetworkStatus();

    // Initialize connection notification service
    initializeConnectionNotifications({
      throttleCooldownMs: 5000,
      showReconnectingAtAttempt: 3,
      // Keep toast away from the bottom-right status pill to avoid overlap
      position: 'top-right',
    });

    // Initialize offline detection in the store
    webSocketStore.initializeOfflineDetection();

    // Load any persisted offline messages from localStorage
    webSocketStore.loadOfflineQueue();

    // Connect WebSocket in the background. The connect handshake takes
    // ~3s on average and the app does NOT need an open WS to render —
    // components reactively update when the store transitions to
    // connected. Awaiting here previously blocked Vue mount for the
    // duration of the handshake, producing a multi-second white page.
    webSocketStore.connect().catch((wsError) => {
      console.warn(
        '[WebSocket Boot] Failed to connect WebSocket, will retry automatically:',
        {
          error: wsError.message || wsError,
          timestamp: new Date().toISOString(),
        },
      );
      // WebSocket store has built-in reconnection logic, so we just log and continue
    });

    // Connect DocNet WebSocket ONLY on DocNet pages (/doc-net/*)
    // Previously connected globally on every page, causing 6 unnecessary API calls
    // (missions 562KB, issues 85KB, emails, inbox, projects, agents) on Dashboard,
    // Field Validation, Settings etc. When DocNet service was down, this blocked
    // ALL pages with 130-260s timeouts.
    const isDocNetPage = (path) => path.startsWith('/doc-net');

    const connectDocNetIfNeeded = async (path) => {
      try {
        const settingStore = useSettingStore();
        if (Object.keys(settingStore.user_settings).length === 0) {
          await settingStore.startSettingsFetch();
          await subscriptionUtil.methods.checkSubscriptionValidity();
        }
        if (toBoolPreference(settingStore.user_settings[CONSTANTS.docnet_setting]) && isDocNetPage(path)) {
          const docNetWsStore = useDocNetWebSocketStore();
          if (!docNetWsStore.connected) {
            await docNetWsStore.connect();
          }
        }
      } catch (docNetWsError) {
        console.warn('[WebSocket Boot] DocNet WS error:', docNetWsError.message || docNetWsError);
      }
    };

    // Fire-and-forget on initial load. Settings fetch + subscription check
    // + optional DocNet connect can take several seconds on the first
    // visit — they must not block Vue mount. The route guards / components
    // that depend on these values already handle the loading state.
    connectDocNetIfNeeded(window.location.pathname);

    // Connect/disconnect on route changes
    router.afterEach((to) => {
      if (isDocNetPage(to.path)) {
        connectDocNetIfNeeded(to.path);
      } else {
        try {
          const docNetWsStore = useDocNetWebSocketStore();
          if (docNetWsStore.connected) {
            docNetWsStore.disconnect();
          }
        } catch { /* store may not be initialized */ }
      }
    });

    // Clean up WebSocket on app close
    // Remove any existing handler first (HMR cleanup)
    if (beforeUnloadHandler) {
      window.removeEventListener('beforeunload', beforeUnloadHandler);
    }
    beforeUnloadHandler = () => {
      webSocketStore.close(); // Close WebSocket before leaving the page
      try {
        useDocNetWebSocketStore().disconnect();
      } catch { /* store may not be initialized */ }
    };
    window.addEventListener('beforeunload', beforeUnloadHandler);

    // Mark as initialized
    isInitialized = true;

    // You can also handle WebSocket reconnection based on route changes
    // router.beforeEach((to, from, next) => {
    //   // Optionally manage WebSocket behavior on route change
    //   next();
    // });

    // Optionally, expose the WebSocket store globally for access in components
    // app.config.globalProperties.$webSocketStore = webSocketStore;
  } catch (err) {
    // Safe error handling with fallback to console
    // This ensures error logging works even if logger boot file hasn't initialized yet
    const error = typeof logError === 'function' ? logError : console.error;
    error('[WebSocket Boot] Error during initialization:', err.message || err);
  }
});

// HMR cleanup - reset state when module is replaced
if (import.meta.hot) {
  import.meta.hot.dispose(() => {
    console.debug('[WebSocket Boot] HMR dispose - cleaning up');
    if (beforeUnloadHandler) {
      window.removeEventListener('beforeunload', beforeUnloadHandler);
      beforeUnloadHandler = null;
    }
    // Clean up network status listeners to prevent memory leaks
    cleanupNetworkStatus();
    isInitialized = false;
  });
}
