/**
 * Connection Notification Service
 *
 * Provides throttled toast notifications for WebSocket connection status changes.
 * Integrates with Quasar's Notify plugin for consistent UI feedback.
 */

import { notify } from 'src/components/notifications/notify';
import {
  WebSocketConnectionState,
  WebSocketError,
} from 'src/types/websocket';

export interface ConnectionNotificationOptions {
  /** Cooldown between similar notifications in ms (default: 5000) */
  throttleCooldownMs: number;
  /** Duration for success notifications in ms (default: 3000) */
  successDurationMs: number;
  /** Duration for warning notifications in ms (default: 5000) */
  warningDurationMs: number;
  /** Duration for error notifications in ms (default: Infinity = persistent until dismiss) */
  errorDurationMs: number;
  /** Show reconnection attempts starting at this attempt number (default: 3) */
  showReconnectingAtAttempt: number;
}

const DEFAULT_OPTIONS: ConnectionNotificationOptions = {
  throttleCooldownMs: 5000,
  successDurationMs: 3000,
  warningDurationMs: 5000,
  errorDurationMs: Infinity, // Persistent
  showReconnectingAtAttempt: 3,
};

type NotificationType = 'connected' | 'disconnected' | 'reconnecting' | 'offline' | 'failed' | 'queued' | 'synced';

export class ConnectionNotificationService {
  private options: ConnectionNotificationOptions;
  private lastNotificationTime: Map<NotificationType, number> = new Map();
  private currentNotificationId: string | number | null = null;

  constructor(options: Partial<ConnectionNotificationOptions> = {}) {
    this.options = { ...DEFAULT_OPTIONS, ...options };
  }

  /**
   * Check if enough time has passed since last notification of this type
   */
  private canShowNotification(type: NotificationType): boolean {
    const lastTime = this.lastNotificationTime.get(type) || 0;
    const now = Date.now();
    return now - lastTime >= this.options.throttleCooldownMs;
  }

  /**
   * Record that a notification was shown
   */
  private recordNotification(type: NotificationType): void {
    this.lastNotificationTime.set(type, Date.now());
  }

  /**
   * Dismiss any current persistent notification
   */
  dismissCurrent(): void {
    if (this.currentNotificationId !== null) {
      notify.dismiss(this.currentNotificationId);
      this.currentNotificationId = null;
    }
  }

  /**
   * Show notification for successful connection
   */
  notifyConnected(): void {
    if (!this.canShowNotification('connected')) return;

    this.dismissCurrent();
    this.recordNotification('connected');

    notify.success('Connection restored', { duration: this.options.successDurationMs });
  }

  /**
   * Show notification when offline
   */
  notifyOffline(): void {
    if (!this.canShowNotification('offline')) return;

    this.dismissCurrent();
    this.recordNotification('offline');

    this.currentNotificationId = notify.warning('Working offline', {
      description: 'Changes will sync when connection is restored',
      duration: this.options.errorDurationMs, // Persistent
    });
  }

  /**
   * Show notification for reconnection attempts (after threshold)
   */
  notifyReconnecting(attempt: number, maxRetries: number): void {
    // Only show after threshold to avoid spamming on quick reconnects
    if (attempt < this.options.showReconnectingAtAttempt) return;
    if (!this.canShowNotification('reconnecting')) return;

    this.dismissCurrent();
    this.recordNotification('reconnecting');

    notify.warning(`Reconnecting... (${attempt}/${maxRetries})`, {
      duration: this.options.warningDurationMs,
    });
  }

  /**
   * Show notification when connection failed (max retries exceeded)
   */
  notifyFailed(error?: WebSocketError): void {
    if (!this.canShowNotification('failed')) return;

    this.dismissCurrent();
    this.recordNotification('failed');

    this.currentNotificationId = notify.error(
      'Connection failed',
      error?.message || 'Unable to connect to server. Please check your network.',
      {
        duration: this.options.errorDurationMs, // Persistent
        action: {
          label: 'Retry',
          onClick: () => {
            this.currentNotificationId = null;
            window.dispatchEvent(new CustomEvent('websocket:retry-requested'));
          },
        },
      },
    );
  }

  /**
   * Show notification when messages are queued for offline sync
   */
  notifyMessageQueued(queueSize: number): void {
    // Don't throttle queue notifications - they should update count
    notify.info(`Message queued (${queueSize} pending)`, { duration: 2000 });
  }

  /**
   * Show notification when offline queue is synced
   */
  notifyQueueSynced(successCount: number, totalCount: number): void {
    if (!this.canShowNotification('synced')) return;

    this.recordNotification('synced');

    const allSuccess = successCount === totalCount;
    const message = allSuccess
      ? `${successCount} messages synced`
      : `${successCount}/${totalCount} messages synced`;

    if (allSuccess) {
      notify.success(message, { duration: this.options.successDurationMs });
    } else {
      notify.warning(message, {
        description: 'Some messages could not be sent',
        duration: this.options.successDurationMs,
      });
    }
  }

  /**
   * Handle state change and show appropriate notification
   */
  handleStateChange(
    newState: WebSocketConnectionState,
    previousState: WebSocketConnectionState,
    error?: WebSocketError | null,
    attempt?: number,
    maxRetries?: number,
  ): void {
    // Connected - only notify if we were disconnected/reconnecting
    if (
      newState === WebSocketConnectionState.CONNECTED &&
      (previousState === WebSocketConnectionState.RECONNECTING ||
        previousState === WebSocketConnectionState.DISCONNECTED ||
        previousState === WebSocketConnectionState.SUSPENDED)
    ) {
      this.notifyConnected();
      return;
    }

    // Offline/Suspended
    if (newState === WebSocketConnectionState.SUSPENDED) {
      this.notifyOffline();
      return;
    }

    // Reconnecting
    if (
      newState === WebSocketConnectionState.RECONNECTING &&
      attempt !== undefined &&
      maxRetries !== undefined
    ) {
      this.notifyReconnecting(attempt, maxRetries);
      return;
    }

    // Failed
    if (newState === WebSocketConnectionState.FAILED) {
      this.notifyFailed(error || undefined);
      return;
    }
  }

  /**
   * Reset throttle timers (useful for testing or manual reset)
   */
  resetThrottle(): void {
    this.lastNotificationTime.clear();
  }
}

// Singleton instance for global use
let connectionNotificationService: ConnectionNotificationService | null = null;

/**
 * Get or create the singleton notification service instance
 */
export function getConnectionNotificationService(
  options?: Partial<ConnectionNotificationOptions>,
): ConnectionNotificationService {
  if (!connectionNotificationService) {
    connectionNotificationService = new ConnectionNotificationService(options);
  }
  return connectionNotificationService;
}

/**
 * Initialize the connection notification service
 * Call this once at app startup (e.g., in boot file)
 */
export function initializeConnectionNotifications(
  options?: Partial<ConnectionNotificationOptions>,
): ConnectionNotificationService {
  connectionNotificationService = new ConnectionNotificationService(options);
  return connectionNotificationService;
}
